  var bytes = aaawzB64ToBytes(String(contentB64).replace(/\s/g, ''));
  if (bytes.length % 2 === 1) bytes.push(0);
  var vals = [];
  for (var i = 0; i < bytes.length; i += 2) vals.push((bytes[i] << 8) | bytes[i + 1]);
  return aaawzLzDecompress(vals);
}
// ---- 辅助函数 (jsLib 顶层, 纯函数: 不依赖 java/source, I/O 由规则层完成) ----
// CP1252 -> ISO-8859-1 逆映射 (修复 0x80-0x9F 高字节损坏)
var aaawzCP1252Rev = {};
(function () {
  var m = {
    0x20ac: 0x80, 0x201a: 0x82, 0x0192: 0x83, 0x201e: 0x84, 0x2026: 0x85,
    0x2020: 0x86, 0x2021: 0x87, 0x02c6: 0x88, 0x2030: 0x89, 0x0160: 0x8a,
    0x2039: 0x8b, 0x0152: 0x8c, 0x017d: 0x8e, 0x2018: 0x91, 0x2019: 0x92,
    0x201c: 0x93, 0x201d: 0x94, 0x2022: 0x95, 0x2013: 0x96, 0x2014: 0x97,
    0x02dc: 0x98, 0x2122: 0x99, 0x0161: 0x9a, 0x203a: 0x9b, 0x0153: 0x9c,
    0x017e: 0x9e, 0x0178: 0x9f
  };
  for (var k in m) aaawzCP1252Rev[k] = m[k];
})();
// 由 latin1 字符串构建映射 (纯 JS, 自动修复 CP1252 高字节 + 支持 hex)
function aaawzBuildMapFromLatin(latin) {
  var bytes;
  if (/^[0-9a-f]+$/i.test(latin) && latin.length % 2 === 0) {
    bytes = new Uint8Array(latin.length >> 1);
    for (var i = 0; i < bytes.length; i++) bytes[i] = parseInt(latin.substr(i * 2, 2), 16);
  } else {
    bytes = new Uint8Array(latin.length);
    for (var i = 0; i < latin.length; i++) {
      var c = latin.charCodeAt(i);
      var b = aaawzCP1252Rev[c];
      bytes[i] = (b !== undefined ? b : c & 0xff);
    }
  }
  var r = aaawzWoff2Parse(bytes);
  var cmapData = r.decompressed.subarray(r.cmap.offset, r.cmap.offset + r.cmap.length);
  var cmap = aaawzParseCmap(cmapData);
  var map = {};
  for (var cp in cmap) {
    var real = aaawzGidReal[cmap[cp]];
    if (real) map[cp] = real;
  }
  return map;
}
// 还原文本 (map: {假cp: 真cp})
function aaawzRestore(text, map) {
  var out = '';
  for (var i = 0; i < text.length; i++) {
    var ch = text.charAt(i);
    var cp = ch.codePointAt ? ch.codePointAt(0) : ch.charCodeAt(0);
    var real = map[cp];
    out += real ? String.fromCharCode(real) : ch;
  }
  return out;
}
// 正文 content 解密 (base64 + LZString)
function aaawzDecodeContent(contentB64) {
  var bytes = aaawzB64ToBytes(String(contentB64).replace(/\s/g, ''));
  if (bytes.length % 2 === 1) bytes.push(0);
  var vals = [];
  for (var i = 0; i < bytes.length; i += 2) vals.push((bytes[i] << 8) | bytes[i + 1]);
  return aaawzLzDecompress(vals);
}
// 规则辅助: 获取字体映射 (含下载+缓存, 需在规则环境调用)
function aaawzRuleGetMap(font) {
  if (!font || !font.url) return null;
  var key = 'aaawz_map_' + String(font.url).split('/').pop();
  var cached = null;
  try { cached = source.get(key); } catch (e) {}
  if (cached) {
    try { return JSON.parse(cached); } catch (e) {}
  }
  var latin = java.ajax(String(font.url) + ',{"charset":"ISO-8859-1"}');
  if (!latin || latin.length < 100) return null;
  var map = aaawzBuildMapFromLatin(latin);
  if (map) {
    try { source.put(key, JSON.stringify(map)); } catch (e) {}
  }
  return map;
}

// ---- v3 LZString 响应解密 ----
// 3A小说 aaawz.cc 响应解密 (base64 + lz-string 自包含, Rhino 兼容)
function _aaazB64(b64){
  var CH = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  var out = '', i, c0, c1, c2, c3;
  for (i = 0; i < b64.length; i += 4) {
    c0 = CH.indexOf(b64.charAt(i));
    c1 = CH.indexOf(b64.charAt(i + 1));
    c2 = b64.charAt(i + 2) === '=' ? -1 : CH.indexOf(b64.charAt(i + 2));
    c3 = b64.charAt(i + 3) === '=' ? -1 : CH.indexOf(b64.charAt(i + 3));
    if (c0 < 0 || c1 < 0) break;
    out += String.fromCharCode((c0 << 2) | (c1 >> 4));
    if (c2 >= 0) out += String.fromCharCode(((c1 & 15) << 4) | (c2 >> 2));
    if (c3 >= 0) out += String.fromCharCode(((c2 & 3) << 6) | c3);
  }
  return out;
}
function decryptAAAZ(b64str){
  var bin = _aaazB64(String(b64str));
  if (bin.length % 2 === 1) bin += String.fromCharCode(0);  // 站点base64多1个padding, 奇数补0
  var len = bin.length >> 1;
  var vals = new Array(len);
  for (var i = 0; i < len; i++) vals[i] = (bin.charCodeAt(i * 2) << 8) | bin.charCodeAt(i * 2 + 1);
  var out = lzDecompress(vals);
  if (out === null || out === undefined) {
    // 字节序 fallback (LE)
    var vals2 = new Array(len);
    for (var j = 0; j < len; j++) vals2[j] = (bin.charCodeAt(j * 2 + 1) << 8) | bin.charCodeAt(j * 2);
    out = lzDecompress(vals2);
  }
  return out;
}
function lzDecompress(values){
  var dict = [0, 1, 2], enlargeIn = 4, dictSize = 4, numBits = 3, w = '', out = [];
  var val = values[0] || 0, position = 32768, index = 1, i, c, entry;
  var maxIter = (values.length + 2) * 64 + 2000, guard = 0;
  function rb(){ var b = val & position; position >>= 1; if (position === 0) { position = 32768; val = index < values.length ? values[index] : 0; index++; } return b ? 1 : 0; }
  function rbits(n){ var b = 0, p = 1; for (i = 0; i < n; i++) { b |= rb() * p; p <<= 1; } return b; }
  c = rbits(2);
  if (c === 0) c = String.fromCharCode(rbits(8));
  else if (c === 1) c = String.fromCharCode(rbits(16));
  else return '';
  dict[3] = c; w = c; out.push(c);
  for (;;) {
    if (++guard > maxIter) return null;
    c = rbits(numBits);
    if (c === 2) return out.join('');
    if (c === 0) { dict[dictSize++] = String.fromCharCode(rbits(8)); c = dictSize - 1; enlargeIn--; }
    else if (c === 1) { dict[dictSize++] = String.fromCharCode(rbits(16)); c = dictSize - 1; enlargeIn--; }
    if (enlargeIn === 0) { enlargeIn = 1 << numBits; numBits++; }
    if (c < dict.length) entry = dict[c];
    else if (c === dictSize) entry = w + w.charAt(0);
    else return null;
    out.push(entry);
    dict[dictSize++] = w + entry.charAt(0);
    enlargeIn--;
    w = entry;
    if (enlargeIn === 0) { enlargeIn = 1 << numBits; numBits++; }
  }
}

function decompressFromBase64(input) {
    if (input == null) return '';
    if (input === '') return null;

    const base64Alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=";
    const lookup = {};
    for (let i = 0; i < base64Alphabet.length; i++) {
        lookup[base64Alphabet.charAt(i)] = i;
    }
    function getValue(char) {
        return lookup[char];
    }

    function decompress(length, resetValue, getNextValue) {
        const dictionary = [];
        let dictSize = 4;
        let bits = 3;
        let result = [];
        let data = { val: getNextValue(0), position: resetValue, index: 1 };

        // 读取初始控制代码（2 位）
        let res = 0;
        let maxPower = Math.pow(2, 2);
        let power = 1;
        while (power != maxPower) {
            let bit = data.val & data.position;
            data.position >>= 1;
            if (data.position == 0) {
                data.position = resetValue;
                if (data.index > length) return '';
                data.val = getNextValue(data.index++);
            }
            res |= (bit > 0 ? 1 : 0) * power;
            power <<= 1;
        }

        let next;
        switch (res) {
            case 0: // 8 位字符
                res = 0;
                maxPower = Math.pow(2, 8);
                power = 1;
                while (power != maxPower) {
                    let bit = data.val & data.position;
                    data.position >>= 1;
                    if (data.position == 0) {
                        data.position = resetValue;
                        if (data.index > length) return '';
                        data.val = getNextValue(data.index++);
                    }
                    res |= (bit > 0 ? 1 : 0) * power;
                    power <<= 1;
                }
                next = String.fromCharCode(res);
                break;
            case 1: // 16 位字符
                res = 0;
                maxPower = Math.pow(2, 16);
                power = 1;
                while (power != maxPower) {
                    let bit = data.val & data.position;
                    data.position >>= 1;
                    if (data.position == 0) {
                        data.position = resetValue;
                        if (data.index > length) return '';
                        data.val = getNextValue(data.index++);
                    }
                    res |= (bit > 0 ? 1 : 0) * power;
                    power <<= 1;
                }
                next = String.fromCharCode(res);
                break;
            case 2: // 结束
                return '';
        }

        // 初始化字典
        dictionary[0] = '';
        dictionary[1] = '';
        dictionary[2] = '';
        dictionary[3] = next;
        let w = next;
        result.push(next);

        // 主解压循环
        while (data.index <= length) {
            let code = 0;
            maxPower = Math.pow(2, bits);
            power = 1;
            while (power != maxPower) {
                let bit = data.val & data.position;
                data.position >>= 1;
                if (data.position == 0) {
                    data.position = resetValue;
                    if (data.index > length) break;
                    data.val = getNextValue(data.index++);
                }
                code |= (bit > 0 ? 1 : 0) * power;
                power <<= 1;
            }

            if (data.index > length && code === 0) break;

            switch (next = code) {
                case 0: // 新 8 位字符
                    res = 0;
                    maxPower = Math.pow(2, 8);
                    power = 1;
                    while (power != maxPower) {
                        let bit = data.val & data.position;
                        data.position >>= 1;
                        if (data.position == 0) {
                            data.position = resetValue;
                            if (data.index > length) return result.join('');
                            data.val = getNextValue(data.index++);
                        }
                        res |= (bit > 0 ? 1 : 0) * power;
                        power <<= 1;
                    }
                    dictionary[dictSize++] = String.fromCharCode(res);
                    next = dictSize - 1;
                    break;
                case 1: // 新 16 位字符
                    res = 0;
                    maxPower = Math.pow(2, 16);
                    power = 1;
                    while (power != maxPower) {
                        let bit = data.val & data.position;
                        data.position >>= 1;
                        if (data.position == 0) {
                            data.position = resetValue;
                            if (data.index > length) return result.join('');
                            data.val = getNextValue(data.index++);
                        }
                        res |= (bit > 0 ? 1 : 0) * power;
                        power <<= 1;
                    }
                    dictionary[dictSize++] = String.fromCharCode(res);
                    next = dictSize - 1;
                    break;
                case 2: // 结束
                    return result.join('');
            }

            if (dictSize - 1 >= Math.pow(2, bits) - 1) bits++;

            let entry;
            if (dictionary[next]) {
                entry = dictionary[next];
            } else if (next === dictSize) {
                entry = w + w.charAt(0);
            } else {
                return null;
            }

            result.push(entry);
            dictionary[dictSize++] = w + entry.charAt(0);
            w = entry;

            if (dictSize - 1 >= Math.pow(2, bits) - 1) bits++;
        }

        return result.join('');
    }

    return decompress(input.length, 32, (index) => getValue(input.charAt(index)));
}

